from fastapi import APIRouter, Depends, HTTPException, Query, status
import hvac

router = APIRouter(prefix="/vault/secrets")

@router.get("/retrieve")
async def retrieve_vault_secret(
    path: str = Query(..., description="Sub-path within tenant secret namespace"),
    vault_client: hvac.Client = Depends(get_vault_client),
    user: AuthUser = Depends(get_authenticated_user)
):
    clean_subpath = path.strip("/").replace("..", "")
    tenant_scoped_path = f"tenants/{user.tenant_id}/{clean_subpath}"

    try:
        secret_version_response = vault_client.secrets.kv.v2.read_secret_version(
            path=tenant_scoped_path,
            mount_point="secret"
        )
        return {
            "path": clean_subpath,
            "data": secret_version_response["data"]["data"]
        }
    except hvac.exceptions.InvalidPath:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Secret path not found in Vault")
    except hvac.exceptions.VaultError as err:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(err))
